@CrossOrigin
@RestController
@RequestMapping("/MetricQuery")
public class MetricQueryRestController extends BaseSpringRestController {
	
	public MetricQueryRestController( MetricService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Metric using a UUID
     * @param		UUID metricId
     * @return		Metric
     */    
    @GetMapping("/load")
    public Metric load( @RequestParam(required=true) UUID metricId ) {
    	Metric entity = null;

    	try {  
    		entity = service.getMetric( new MetricFetchOneSummary( metricId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Metric using Id " + metricId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Metric business objects
     * @return		Set<Metric>
     */
    @GetMapping("/")
    public List<Metric> loadAll() {                
    	List<Metric> metricList = null;
        
    	try {
            // load the Metric
            metricList = service.getAllMetric();
            
            if ( metricList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Metrics" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Metrics ", exc );
        	return null;
        }

        return metricList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Metric metric = null;
    protected MetricService service = null;
    private static final Logger LOGGER = Logger.getLogger(MetricQueryRestController.class.getName());
    
}
